int32_t GdDict::find_index(const GdVal& key, uint64_t h) const {
    if (!buckets || bucket_cap == 0) {
        for (uint32_t i = 0; i < len; ++i) {
            if (entries[i].hash == h && gd_eq(entries[i].key, key)) return static_cast<int32_t>(i);
        }
        return -1;
    }
    if(integer_grid_detail::enabled(*this)) {
        int32_t slot;
        if(integer_grid_detail::query_slot(key,slot)) {
            const int32_t index=slot<0?-1:buckets[uint32_t(slot)];
            return index>=0 && entries[index].hash==h?index:-1;
        }
        // Unknown types, subnormals and nonfinite inputs retain the original
        // hash and equality operations. The table contains only finite Vec2 keys.
        for(uint32_t i=0;i<len;++i)
            if(entries[i].hash==h && gd_eq(entries[i].key,key))return int32_t(i);
        return -1;
    }
    uint32_t mask = bucket_cap - 1;
    uint32_t pos = static_cast<uint32_t>(h) & mask;
    while (true) {
        int32_t ei = buckets[pos];
        if (ei < 0) return -1;
        if (entries[ei].hash == h && gd_eq(entries[ei].key, key)) return ei;
        pos = (pos + 1) & mask;
    }
}
// Specialize only the exact pure branches of gd_eq; retain the original
// evaluator for every floating, mixed numeric, recursive or unknown key.
static inline bool native_dict_scalar_key_equal(const GdVal& a,const GdVal& b) {
    if(a.kind==b.kind) {
        switch(a.kind) {
            case GdVal::Kind::Int:return a.i==b.i;
            case GdVal::Kind::Obj:return a.obj==b.obj;
            case GdVal::Kind::Str:
                if(a.str==b.str)return true;
                if(!a.str || !b.str)return false;
                return a.str->len==b.str->len && a.str->hash==b.str->hash &&
                    std::memcmp(a.str->data,b.str->data,a.str->len)==0;
            default:break;
        }
    }
    return gd_eq(a,b);
}

